window.DemoAPI = (function () {
  const D = window.DEMO_DATA;
  const PUBLIC = ['RoomID','Building','Room','Room Type','Department','College','Zone','CTL Supported','Record Type','Photos URL','Help / Ticket Website','Archived'];
  const EMPLOYEE = PUBLIC.filter(f => f !== 'Photos URL').concat(['Primary Support Unit','Building Number','Reservations','Seating Capacity','Square Footage','Seating Configuration','Floor Type','PC Port','AV Port']);
  const CONTACT = ['Primary Support Unit','Help / Ticket Website','AV Support Contact','AV Support Email','AV Support Phone','Department Contact','Department Contact Email','Department Contact Phone','Computer Support Contact','Computer Support Email','Computer Support Phone'];
  const LIST_FIELDS = ['Department','College','Primary Support Unit'];
  const LOCKED = ['RoomID','Building','Room','Building Number'];
  const pick = (r, f) => { const o = {}; f.forEach(k => o[k] = r[k] == null ? '' : r[k]); return o; };
  const copy = x => JSON.parse(JSON.stringify(x));
  const view = role => ['Technician','Admin'].includes(role);
  const isArch = r => String(r.Archived || '').toLowerCase() === 'yes';
  function rooms(role) {
    if (view(role)) return copy(D.rooms);
    const list = role ? D.rooms : D.rooms.filter(r => !isArch(r));
    return list.map(r => pick(r, role === 'Student' ? PUBLIC.concat(CONTACT) : role === 'Viewer' ? EMPLOYEE : PUBLIC));
  }
  function log(room, action, field, o, n) { D.log.push({ Timestamp: new Date().toISOString().slice(0, 16).replace('T', ' '), User: 'demo@example.com', RoomID: room ? room.RoomID : '', Room: room ? room.Building + ' ' + room.Room : '', Action: action, Field: field || '', 'Old Value': o == null ? '' : String(o), 'New Value': n == null ? '' : String(n) }); }
  const prooms = q => String(q.Rooms || '').split(/[,;\s]+/).filter(Boolean);
  function plog(q, action, field, o, n) { D.log.push({ Timestamp: new Date().toISOString().slice(0, 16).replace('T', ' '), User: 'demo@example.com', RoomID: q.ProjectID, Room: q.Title, Action: action, Field: field || '', 'Old Value': o == null ? '' : String(o), 'New Value': n == null ? '' : String(n) }); }
  function tally(items) { const m = {}; items.forEach(i => { const k = i.Category + '||' + i.Model; const q = i.Qty === '' || i.Qty == null ? null : +i.Qty; if (!(k in m)) m[k] = q; else if (m[k] !== null && q !== null) m[k] += q; }); return m; }
  async function call(action, p, role) {
    await new Promise(r => setTimeout(r, 120));
    const need = roles => { if (!roles.includes(role)) throw new Error('Your role cannot do that.'); };
    const ED = ['Technician','Admin'];
    switch (action) {
      case 'public': return { ok: true, rooms: rooms(null) };
      case 'session': return { ok: true, user: { name: 'Demo ' + role, email: 'demo@example.com', role }, rooms: rooms(role), zones: role === 'Viewer' ? [] : copy(D.zones), lists: copy(D.lists), equipment: view(role) ? copy(D.equipment) : [], catalog: view(role) ? copy(D.catalog) : [], projects: ED.includes(role) ? copy(D.projects) : [] };
      case 'saveRoom': { need(ED); const r = D.rooms.find(x => x.RoomID === p.roomId);
        Object.keys(p.changes).filter(k => !LOCKED.includes(k)).forEach(k => {
          const v = String(p.changes[k]).trim();
          if (LIST_FIELDS.includes(k) && v && !D.lists[k].includes(v)) { if (role !== 'Admin') throw new Error('Pick a ' + k + ' from the list. Only admins can add new names.'); D.lists[k].push(v); D.lists[k].sort(); }
          log(r, 'Edit room', k, r[k], v); r[k] = v; });
        return { ok: true, room: copy(r), lists: copy(D.lists) }; }
      case 'archiveRoom': { need(['Admin']); const r = D.rooms.find(x => x.RoomID === p.roomId); r.Archived = p.archived ? 'Yes' : ''; log(r, p.archived ? 'Archive room' : 'Unarchive room'); return { ok: true, room: copy(r) }; }
      case 'addRoom': { need(['Admin']); const id = 'D' + String(D.rooms.length + 1).padStart(4, '0'); const r = Object.assign({ RoomID: id }, p.room); D.rooms.push(r); log(r, 'Add room'); return { ok: true, room: copy(r) }; }
      case 'removeRoom': { need(ED); const r = D.rooms.find(x => x.RoomID === p.roomId); log(r, 'Remove room'); D.rooms = D.rooms.filter(x => x.RoomID !== p.roomId); return { ok: true }; }
      case 'saveEquipment': { need(ED); const r = D.rooms.find(x => x.RoomID === p.roomId);
        const before = tally(D.equipment.filter(e => e.RoomID === p.roomId)), after = tally(p.items);
        const qt = q => q === null ? '?' : q;
        Object.keys(before).forEach(k => { const [c, m] = k.split('||'); if (!(k in after)) log(r, 'Remove equipment', c, m + ' ×' + qt(before[k]), ''); else if (String(before[k]) !== String(after[k])) log(r, 'Change quantity', c + ': ' + m, qt(before[k]), qt(after[k])); });
        Object.keys(after).forEach(k => { const [c, m] = k.split('||'); if (!(k in before)) log(r, 'Add equipment', c, '', m + ' ×' + qt(after[k])); });
        D.equipment = D.equipment.filter(e => e.RoomID !== p.roomId).concat(p.items.map(i => Object.assign({ RoomID: p.roomId }, i)));
        p.items.forEach(i => { if (!D.catalog.some(c => c.Category === i.Category && c.Model === i.Model)) D.catalog.push({ Category: i.Category, Model: i.Model, 'Last Price Paid': '' }); });
        return { ok: true, equipment: copy(D.equipment.filter(e => e.RoomID === p.roomId)), catalog: copy(D.catalog) }; }
      case 'saveCatalogItem': { need(ED); let c = D.catalog.find(x => x.Category === p.category && x.Model === p.oldModel); if (!c) { c = { Category: p.category, Model: p.model, 'Last Price Paid': p.price }; D.catalog.push(c); } else { if (c.Model !== p.model) D.equipment.forEach(e => { if (e.Category === p.category && e.Model === c.Model) e.Model = p.model; }); c.Model = p.model; c['Last Price Paid'] = p.price; } return { ok: true, catalog: copy(D.catalog), equipment: copy(D.equipment) }; }
      case 'deleteCatalogItem': { need(['Admin']); const arch = id => { const r = D.rooms.find(x => x.RoomID === id); return r && String(r.Archived || '').toLowerCase() === 'yes'; }; const n = new Set(D.equipment.filter(e => e.Category === p.category && e.Model === p.model && !arch(e.RoomID)).map(e => e.RoomID)).size; if (n) throw new Error('This model is still in ' + n + ' active room(s). Change or remove it there first.'); D.catalog = D.catalog.filter(c => !(c.Category === p.category && c.Model === p.model)); return { ok: true, catalog: copy(D.catalog) }; }
      case 'saveZone': { need(ED); const i = D.zones.findIndex(z => z.Zone === p.originalZone); if (i >= 0) { if (p.originalZone !== p.zone.Zone) D.rooms.forEach(r => { if (r.Zone === p.originalZone) r.Zone = p.zone.Zone; }); D.zones[i] = p.zone; } else D.zones.push(p.zone); return { ok: true, zones: copy(D.zones), rooms: rooms(role) }; }
      case 'history': { need(['Technician','Admin']); const ids = new Set([p.roomId].concat(D.projects.filter(x => prooms(x).includes(p.roomId)).map(x => x.ProjectID))); return { ok: true, history: D.log.filter(h => ids.has(h.RoomID)).slice().reverse() }; }
      case 'projectHistory': need(ED); return { ok: true, history: D.log.filter(h => h.RoomID === p.projectId).slice().reverse() };
      case 'saveProject': { need(ED); const q = Object.assign({}, p.project); if (!String(q.Title || '').trim()) throw new Error('Give the project a title');
        const today = new Date().toISOString().slice(0, 10); const name = id => { const r = D.rooms.find(x => x.RoomID === id); return r ? r.Building + ' ' + r.Room : id; };
        q.Rooms = prooms(q).filter(id => D.rooms.some(r => r.RoomID === id)).join(', ');
        let old = D.projects.find(x => x.ProjectID === q.ProjectID);
        if (!old) { q.ProjectID = 'P' + String(D.projects.reduce((m, x) => Math.max(m, +x.ProjectID.slice(1)), 0) + 1).padStart(4, '0'); q.Created = today; q['Created By'] = 'demo@example.com'; if (!q[q.Phase + ' On']) q[q.Phase + ' On'] = today; D.projects.push(q); plog(q, 'Create project', 'Phase', '', q.Phase); prooms(q).forEach(id => log({ RoomID: id, Building: name(id), Room: '' }, 'Link project', q.ProjectID, '', q.Title)); }
        else { if (old.Phase !== q.Phase && !q[q.Phase + ' On']) q[q.Phase + ' On'] = today;
          Object.keys(q).forEach(k => { if (['ProjectID','Created','Created By','Rooms'].includes(k) || String(old[k] == null ? '' : old[k]) === String(q[k] == null ? '' : q[k])) return; plog(q, k === 'Phase' ? 'Project phase' : 'Edit project', k, old[k], q[k]); });
          const b = prooms(old), a = prooms(q); a.filter(x => !b.includes(x)).forEach(id => log({ RoomID: id, Building: name(id), Room: '' }, 'Link project', q.ProjectID, '', q.Title)); b.filter(x => !a.includes(x)).forEach(id => log({ RoomID: id, Building: name(id), Room: '' }, 'Unlink project', q.ProjectID, q.Title, ''));
          D.projects[D.projects.indexOf(old)] = q; }
        const changed = [];
        if (q.Phase === 'Completed' && (!old || old.Phase !== 'Completed') && p.updateRooms !== false) {
          const done = String(q['Completed On'] || today).slice(0, 10);
          const set = { 'Latest Update': done.slice(0, 4) + ' - ' + (q['Project Type'] || 'Complete Upgrade'), 'Equipment Info As Of': done, 'Planned Update Year': '', 'Funding Status': '', 'Funding Source': '' };
          prooms(q).forEach(id => { const r = D.rooms.find(x => x.RoomID === id); if (!r) return; Object.keys(set).forEach(f => { if (String(r[f] == null ? '' : r[f]) !== String(set[f])) { log(r, 'Project completed', f, r[f], set[f] + ' (' + q.ProjectID + ')'); r[f] = set[f]; } }); changed.push(copy(r)); });
        }
        return { ok: true, projects: copy(D.projects), project: copy(q), rooms: changed }; }
      case 'deleteProject': { need(['Admin']); const q = D.projects.find(x => x.ProjectID === p.projectId); if (!q) throw new Error('Project not found'); plog(q, 'Delete project', 'Phase', q.Phase, ''); D.projects = D.projects.filter(x => x !== q); return { ok: true, projects: copy(D.projects) }; }
      case 'listUsers': need(['Admin']); return { ok: true, users: copy(D.users) };
      case 'saveUser': { need(['Admin']); const i = D.users.findIndex(u => u.Email === p.originalEmail); if (i >= 0) D.users[i] = p.user; else D.users.push(p.user); return { ok: true, users: copy(D.users) }; }
    }
    throw new Error('Unknown action');
  }
  return { call };
})();
